insert into story_versions (id, story_id, lang, language, level, meta, description)
values
  ('cly0lit000000000000000011', 'cly0lit000000000000000010', 'es', 'Spanish', 'B1', 'Spanish · B1', 'Un viejo farero descubre una botella misteriosa en la orilla y su vida cambia para siempre.'),
  ('cly0lit000000000000000012', 'cly0lit000000000000000010', 'fr', 'French', 'B1', 'French · B1', 'Un vieux gardien de phare découvre une bouteille mystérieuse sur le rivage et sa vie change pour toujours.'),
  ('cly0mkt000000000000000014', 'cly0mkt000000000000000013', 'es', 'Spanish', 'A2', 'Spanish · A2', 'Una niña visita el mercado del pueblo con su abuela y aprende el valor de las cosas simples.'),
  ('cly0mkt000000000000000015', 'cly0mkt000000000000000013', 'fr', 'French', 'A2', 'French · A2', 'Une petite fille visite le marché du village avec sa grand-mère et apprend la valeur des choses simples.'),
  ('cly0sil000000000000000017', 'cly0sil000000000000000016', 'es', 'Spanish', 'C1', 'Spanish · C1', 'Una arquitecta obsesionada con el silencio diseña un edificio que cambia la forma en que una ciudad entera escucha.'),
  ('cly0sil000000000000000018', 'cly0sil000000000000000016', 'fr', 'French', 'C1', 'French · C1', 'Une architecte obsédée par le silence conçoit un bâtiment qui change la façon dont toute une ville écoute.'),
  ('cly0dog000000000000000020', 'cly0dog000000000000000019', 'es', 'Spanish', 'A1', 'Spanish · A1', 'Un niño describe su día favorito con su perro Bruno en el parque.'),
  ('cly0dog000000000000000021', 'cly0dog000000000000000019', 'fr', 'French', 'A1', 'French · A1', 'Un enfant décrit sa journée préférée avec son chien Bruno au parc.'),
  ('cly0trn000000000000000023', 'cly0trn000000000000000022', 'es', 'Spanish', 'B2', 'Spanish · B2', 'Una joven periodista pierde el último tren a Sevilla y conoce a un desconocido que cambia su perspectiva sobre el tiempo.'),
  ('cly0trn000000000000000024', 'cly0trn000000000000000022', 'fr', 'French', 'B2', 'French · B2', 'Une jeune journaliste rate le dernier train pour Séville et rencontre un inconnu qui change sa perspective sur le temps.'),
  ('cly0map000000000000000026', 'cly0map000000000000000025', 'es', 'Spanish', 'C2', 'Spanish · C2', 'Un neurocientífico que cartografía recuerdos ajenos se enfrenta a la pregunta de si la identidad sobrevive cuando la memoria desaparece.'),
  ('cly0map000000000000000027', 'cly0map000000000000000025', 'fr', 'French', 'C2', 'French · C2', 'Un neuroscientifique qui cartographie les souvenirs d''autrui se confronte à la question de savoir si l''identité survit quand la mémoire disparaît.')
insert into story_lines (id, version_id, position, text, en)
values
  ('18a85f85-0cf2-4d49-9eb2-dcd393a64630', 'cly0lit000000000000000011', 0, 'En una pequeña isla al norte, vivía un viejo farero llamado Tomás.', 'On a small island in the north, there lived an old lighthouse keeper named Tomás.'),
  ('519ae03b-b38a-4d11-881b-2dcc31214365', 'cly0lit000000000000000011', 1, 'Cada noche encendía la gran luz para guiar a los barcos en la oscuridad.', 'Every night he lit the great light to guide ships through the darkness.'),
  ('b0af47ce-c9ea-402e-97af-786f4b5e1695', 'cly0lit000000000000000011', 2, 'Tomás llevaba treinta años solo en la isla, sin más compañía que el mar.', 'Tomás had spent thirty years alone on the island, with no company but the sea.'),
  ('fc2da7d8-1d8f-4a4b-88c1-c1d02e102a78', 'cly0lit000000000000000011', 3, 'Una mañana fría de octubre, encontró una botella de vidrio verde en la orilla.', 'One cold October morning, he found a green glass bottle on the shore.'),
  ('47a8736b-786c-44ac-9c25-e9dfea441206', 'cly0lit000000000000000011', 4, 'Dentro había una carta escrita con tinta azul y letra muy pequeña.', 'Inside was a letter written in blue ink with very small handwriting.'),
  ('13ead937-aeae-4f1c-991e-04c9eb7f416e', 'cly0lit000000000000000011', 5, 'La carta decía: ''Si lees esto, significa que el mar te ha elegido.''', 'The letter read: ''If you read this, it means the sea has chosen you.'''),
  ('1e5f9a49-1788-4822-a4fb-e3b9e5a86ada', 'cly0lit000000000000000011', 6, 'Tomás leyó la carta tres veces, sin entender completamente su significado.', 'Tomás read the letter three times, without fully understanding its meaning.'),
  ('a70ec836-b3dc-470c-a5d5-40853fb2930d', 'cly0lit000000000000000011', 7, 'Esa noche, mientras encendía el faro, vio una luz extraña en el horizonte.', 'That night, while lighting the lighthouse, he saw a strange light on the horizon.'),
  ('0026d0b1-20dd-44d1-af84-0a1b80f6a0d8', 'cly0lit000000000000000011', 8, 'No era un barco normal — la luz era de color violeta y se movía lentamente.', 'It was not a normal ship — the light was violet and moved slowly.'),
  ('ec4dd44c-0d3e-4db9-82b4-52048b5cf282', 'cly0lit000000000000000011', 9, 'Tomás tomó su bote pequeño y remó hacia la luz con el corazón acelerado.', 'Tomás took his small boat and rowed toward the light with his heart racing.'),
  ('0cfbe1eb-5138-4820-9c55-c483d85e9599', 'cly0lit000000000000000011', 10, 'Cuando llegó al lugar, solo encontró un cofre de madera flotando en el agua.', 'When he arrived at the spot, he found only a wooden chest floating in the water.'),
  ('5fdb451f-f81c-4dc5-929a-705e22dec275', 'cly0lit000000000000000011', 11, 'El cofre estaba cerrado con un candado con la forma de una estrella de mar.', 'The chest was locked with a padlock in the shape of a starfish.'),
  ('bb01ab98-83cd-419c-a4fc-da1eaa4b4234', 'cly0lit000000000000000011', 12, 'Recordó que en su bolsillo llevaba una llave vieja que había encontrado años atrás.', 'He remembered that in his pocket he carried an old key he had found years ago.'),
  ('5c24cda5-aff1-43ad-a72b-7ad614730d46', 'cly0lit000000000000000011', 13, 'Con manos temblorosas, introdujo la llave en el candado — y abrió perfectamente.', 'With trembling hands, he inserted the key into the lock — and it opened perfectly.'),
  ('b37ffc61-d8e4-44a9-9c4c-163d99e85f1a', 'cly0lit000000000000000011', 14, 'Dentro del cofre había un mapa, una brújula de plata y una segunda carta.', 'Inside the chest was a map, a silver compass, and a second letter.'),
  ('1c18aade-7c4c-4c2e-9c6b-b371a29f3503', 'cly0lit000000000000000011', 15, 'La segunda carta decía: ''El tesoro no es el oro, sino lo que encontrarás en el camino.''', 'The second letter read: ''The treasure is not gold, but what you will find along the way.'''),
  ('59b3bdb7-fbb1-4e69-b142-a630cbdb2be2', 'cly0lit000000000000000011', 16, 'Tomás pasó toda la noche mirando el mapa a la luz de su linterna.', 'Tomás spent the whole night studying the map by the light of his lantern.'),
  ('7d4c82cf-cee6-4671-8d4c-b5c130ac4eec', 'cly0lit000000000000000011', 17, 'Por primera vez en treinta años, sintió que su vida tenía una nueva dirección.', 'For the first time in thirty years, he felt that his life had a new direction.'),
  ('e143321c-ee10-4686-8392-0a5e3b013a9b', 'cly0lit000000000000000011', 18, 'A la mañana siguiente, preparó su bote y comenzó el viaje que el mapa indicaba.', 'The following morning, he prepared his boat and began the journey the map indicated.'),
  ('d9a1b26d-8ccd-4528-bb35-4b5cea2e86ae', 'cly0lit000000000000000011', 19, 'El viejo farero dejó la isla por primera vez, sonriendo hacia el horizonte abierto.', 'The old lighthouse keeper left the island for the first time, smiling toward the open horizon.'),
  ('24e501e8-2348-4bfb-a436-1e00a27a0082', 'cly0lit000000000000000012', 0, 'Sur une petite île au nord, vivait un vieux gardien de phare nommé Thomas.', 'On a small island in the north, there lived an old lighthouse keeper named Thomas.'),
  ('2d888d0b-5789-48b9-9b8d-eef4546ba4f3', 'cly0lit000000000000000012', 1, 'Chaque nuit, il allumait la grande lumière pour guider les navires dans l''obscurité.', 'Every night he lit the great light to guide ships through the darkness.'),
  ('f5193b7a-e287-4be3-8df5-3541476b154b', 'cly0lit000000000000000012', 2, 'Thomas vivait seul sur l''île depuis trente ans, sans autre compagnie que la mer.', 'Thomas had spent thirty years alone on the island, with no company but the sea.'),
  ('58c9c4e7-6a63-44b5-89fe-4f9ccbbc4783', 'cly0lit000000000000000012', 3, 'Un matin froid d''octobre, il trouva une bouteille en verre vert sur le rivage.', 'One cold October morning, he found a green glass bottle on the shore.'),
  ('06b9f26b-4cc0-452c-b4d3-aaf28d7c1e67', 'cly0lit000000000000000012', 4, 'À l''intérieur se trouvait une lettre écrite à l''encre bleue avec une très petite écriture.', 'Inside was a letter written in blue ink with very small handwriting.'),
  ('b6afa897-8def-4075-94d4-cd6f3d37a886', 'cly0lit000000000000000012', 5, 'La lettre disait : ''Si tu lis ceci, cela signifie que la mer t''a choisi.''', 'The letter read: ''If you read this, it means the sea has chosen you.'''),
  ('7b0f4523-fb91-4f0d-9e26-e594adb237cc', 'cly0lit000000000000000012', 6, 'Thomas lut la lettre trois fois, sans en comprendre complètement le sens.', 'Thomas read the letter three times, without fully understanding its meaning.'),
  ('9322f609-dc10-4772-9afc-5bb670ff865d', 'cly0lit000000000000000012', 7, 'Ce soir-là, en allumant le phare, il vit une lumière étrange à l''horizon.', 'That night, while lighting the lighthouse, he saw a strange light on the horizon.'),
  ('ddf69aa8-6b90-425a-97a2-e3e67792720c', 'cly0lit000000000000000012', 8, 'Ce n''était pas un navire ordinaire — la lumière était violette et se déplaçait lentement.', 'It was not a normal ship — the light was violet and moved slowly.'),
  ('9badfbf4-47f0-4473-a8cc-add0c0acc435', 'cly0lit000000000000000012', 9, 'Thomas prit son petit bateau et rama vers la lumière, le cœur battant.', 'Tomás took his small boat and rowed toward the light with his heart racing.'),
  ('910af647-8fa1-48e6-892f-8b9b885b220d', 'cly0lit000000000000000012', 10, 'Quand il arriva à l''endroit, il ne trouva qu''un coffre en bois flottant sur l''eau.', 'When he arrived at the spot, he found only a wooden chest floating in the water.'),
  ('85bdef8d-a7f1-4e95-a8c2-6d1744320ec9', 'cly0lit000000000000000012', 11, 'Le coffre était fermé par un cadenas en forme d''étoile de mer.', 'The chest was locked with a padlock in the shape of a starfish.'),
  ('181a9ce6-d3bf-41b1-82e1-e9670bc52b1a', 'cly0lit000000000000000012', 12, 'Il se souvint qu''il portait dans sa poche une vieille clé trouvée des années auparavant.', 'He remembered that in his pocket he carried an old key he had found years ago.'),
  ('8b547b68-5377-491c-bb6f-7e2d56c492b4', 'cly0lit000000000000000012', 13, 'D''une main tremblante, il introduisit la clé dans le cadenas — et il s''ouvrit parfaitement.', 'With trembling hands, he inserted the key into the lock — and it opened perfectly.'),
  ('63a73818-eec9-4740-b598-c9af94a2690e', 'cly0lit000000000000000012', 14, 'Dans le coffre se trouvaient une carte, une boussole en argent et une deuxième lettre.', 'Inside the chest was a map, a silver compass, and a second letter.'),
  ('5a759947-c625-4488-b579-cc24a6ce79e4', 'cly0lit000000000000000012', 15, 'La deuxième lettre disait : ''Le trésor n''est pas l''or, mais ce que tu trouveras en chemin.''', 'The second letter read: ''The treasure is not gold, but what you will find along the way.'''),
  ('1e23cddb-4b7e-4e56-b931-3ceddedb10e8', 'cly0lit000000000000000012', 16, 'Thomas passa toute la nuit à regarder la carte à la lumière de sa lanterne.', 'Thomas spent the whole night studying the map by the light of his lantern.'),
  ('2793105f-132b-4a5f-a44b-ba3d3247051e', 'cly0lit000000000000000012', 17, 'Pour la première fois depuis trente ans, il sentit que sa vie avait une nouvelle direction.', 'For the first time in thirty years, he felt that his life had a new direction.'),
  ('cb1ff18a-0aa7-4f75-aba6-f09a4a1cc852', 'cly0lit000000000000000012', 18, 'Le lendemain matin, il prépara son bateau et commença le voyage indiqué par la carte.', 'The following morning, he prepared his boat and began the journey the map indicated.'),
  ('4e01ef8f-1084-475e-80d4-b907c956b7f3', 'cly0lit000000000000000012', 19, 'Le vieux gardien de phare quitta l''île pour la première fois, souriant vers l''horizon ouvert.', 'The old lighthouse keeper left the island for the first time, smiling toward the open horizon.'),
  ('4e860ced-0afc-4960-a431-aef6a231f9e5', 'cly0mkt000000000000000014', 0, 'Cada sábado, Lucía iba al mercado con su abuela.', 'Every Saturday, Lucía went to the market with her grandmother.'),
  ('d551618e-4603-4944-9dcd-c05588df7c20', 'cly0mkt000000000000000014', 1, 'El mercado estaba lleno de colores, olores y sonidos.', 'The market was full of colors, smells and sounds.'),
  ('ad08a2bc-3805-457e-a7fa-479f167b3bbc', 'cly0mkt000000000000000014', 2, 'Había tomates rojos, limones amarillos y hierbas verdes.', 'There were red tomatoes, yellow lemons and green herbs.'),
  ('942a9f14-d1ea-49d5-82f9-ca3f627ece35', 'cly0mkt000000000000000014', 3, 'La abuela siempre saludaba a todos los vendedores por su nombre.', 'Grandmother always greeted all the sellers by name.'),
  ('c664a55f-f6d1-4aa4-b799-18e311c8d946', 'cly0mkt000000000000000014', 4, '— Buenos días, Ramón. ¿Están frescos los huevos hoy? —preguntó.', '"Good morning, Ramón. Are the eggs fresh today?" she asked.'),
  ('98546226-758c-4980-8e22-6c6b2fe7c45b', 'cly0mkt000000000000000014', 5, '— Fresquísimos, señora Carmen. Los traje esta mañana —respondió él.', '"Very fresh, Mrs Carmen. I brought them this morning," he replied.'),
  ('6fe0b472-831f-48eb-a83c-5108725e10a4', 'cly0mkt000000000000000014', 6, 'Lucía miraba todo con ojos grandes y curiosos.', 'Lucía watched everything with big, curious eyes.'),
  ('32acbaf1-b5a3-4b17-8e75-13af95aae129', 'cly0mkt000000000000000014', 7, 'Le gustaba especialmente el puesto de frutas tropicales.', 'She especially liked the tropical fruit stall.'),
  ('7cb0ccab-efeb-4e6f-a270-134c9326b775', 'cly0mkt000000000000000014', 8, 'Había mangos, papayas y piñas que nunca veía en las tiendas normales.', 'There were mangoes, papayas and pineapples she never saw in normal shops.'),
  ('94b81351-18ec-4e80-84ef-0c5091616573', 'cly0mkt000000000000000014', 9, '— Abuela, ¿puedo probar un trozo de mango? —preguntó Lucía.', '"Grandmother, can I try a piece of mango?" asked Lucía.'),
  ('9fb79234-6b0b-4e81-a811-8d2a41f46066', 'cly0mkt000000000000000014', 10, '— Claro que sí, mi amor —dijo la abuela sonriendo.', '"Of course, my love," said grandmother smiling.'),
  ('e590f88b-b0e0-4228-a1b3-8581f6eaba5a', 'cly0mkt000000000000000014', 11, 'El vendedor le dio un trozo grande y dulce sin cobrar nada.', 'The seller gave her a large, sweet piece without charging anything.'),
  ('47778d92-f281-4f13-9658-922ddff5f314', 'cly0mkt000000000000000014', 12, 'Lucía cerró los ojos al probarlo — era el mejor sabor del mundo.', 'Lucía closed her eyes tasting it — it was the best flavor in the world.'),
  ('5e29ae46-f851-4971-8a59-c8009133bf57', 'cly0mkt000000000000000014', 13, 'Después fueron al puesto de pan recién horneado.', 'Afterwards they went to the freshly baked bread stall.'),
  ('892a27ca-e3d6-46ca-b4e2-0da5a6d78722', 'cly0mkt000000000000000014', 14, 'El olor era tan rico que Lucía se detuvo en seco.', 'The smell was so wonderful that Lucía stopped in her tracks.'),
  ('14e37290-8205-458a-a0f3-5faf3f4c8eae', 'cly0mkt000000000000000014', 15, 'La abuela compró una hogaza grande y dos bollos de canela.', 'Grandmother bought a large loaf and two cinnamon rolls.'),
  ('d293e258-d2bb-4090-81f5-031e4e454d47', 'cly0mkt000000000000000014', 16, 'Al final del recorrido, Lucía llevaba una bolsa llena de cosas buenas.', 'At the end of the tour, Lucía was carrying a bag full of good things.'),
  ('05ddc7c2-e651-4c13-ab60-25400891e027', 'cly0mkt000000000000000014', 17, '— ¿Por qué no compramos en el supermercado como todos? —preguntó.', '"Why don''t we shop at the supermarket like everyone else?" she asked.'),
  ('84661704-a520-46e0-82d3-87f240d04811', 'cly0mkt000000000000000014', 18, 'La abuela se detuvo y la miró con una sonrisa tranquila.', 'Grandmother stopped and looked at her with a calm smile.'),
  ('1b3612c9-7da7-45c2-8eeb-ac85a101e0b9', 'cly0mkt000000000000000014', 19, '— Porque aquí no solo compramos comida. Compramos historias —dijo.', '"Because here we don''t just buy food. We buy stories," she said.'),
  ('19325538-7ede-43bf-bc59-bc553ec4d68e', 'cly0mkt000000000000000015', 0, 'Chaque samedi, Lucie allait au marché avec sa grand-mère.', 'Every Saturday, Lucie went to the market with her grandmother.'),
  ('29211e36-3a18-4779-b9b6-7a354c1e633a', 'cly0mkt000000000000000015', 1, 'Le marché était plein de couleurs, d''odeurs et de sons.', 'The market was full of colors, smells and sounds.'),
  ('a68a7316-c05e-4fc2-8ae9-5024da67c84c', 'cly0mkt000000000000000015', 2, 'Il y avait des tomates rouges, des citrons jaunes et des herbes vertes.', 'There were red tomatoes, yellow lemons and green herbs.'),
  ('fc183700-78a6-4a4e-80c5-8ef721b63c7e', 'cly0mkt000000000000000015', 3, 'La grand-mère saluait toujours tous les vendeurs par leur prénom.', 'Grandmother always greeted all the sellers by name.'),
  ('d0250828-76dd-4ad9-9584-d86bd218ffce', 'cly0mkt000000000000000015', 4, '— Bonjour, Raymond. Les œufs sont frais aujourd''hui ? —demanda-t-elle.', '"Good morning, Raymond. Are the eggs fresh today?" she asked.'),
  ('7c5963be-f51b-4a4b-ad70-3835a6264cc9', 'cly0mkt000000000000000015', 5, '— Très frais, madame Carmen. Je les ai apportés ce matin —répondit-il.', '"Very fresh, Mrs Carmen. I brought them this morning," he replied.'),
  ('a81b6714-c217-4665-bd64-cefe18bd5d42', 'cly0mkt000000000000000015', 6, 'Lucie regardait tout avec de grands yeux curieux.', 'Lucie watched everything with big, curious eyes.'),
  ('d84ef198-0680-4130-a6f3-eff1871d00b0', 'cly0mkt000000000000000015', 7, 'Elle aimait particulièrement l''étal de fruits tropicaux.', 'She especially liked the tropical fruit stall.'),
  ('f1eecdbd-50b1-473b-aa9c-b8f19b94f476', 'cly0mkt000000000000000015', 8, 'Il y avait des mangues, des papayes et des ananas qu''elle ne voyait jamais dans les magasins normaux.', 'There were mangoes, papayas and pineapples she never saw in normal shops.'),
  ('fa4770fb-e3de-412d-ad83-0c55ddf73cfd', 'cly0mkt000000000000000015', 9, '— Grand-mère, est-ce que je peux goûter un morceau de mangue ? —demanda Lucie.', '"Grandmother, can I try a piece of mango?" asked Lucie.'),
  ('553cbcd0-7fee-4b9f-819f-85639778b4ed', 'cly0mkt000000000000000015', 10, '— Bien sûr, mon amour —dit la grand-mère en souriant.', '"Of course, my love," said grandmother smiling.'),
  ('4b937c0c-ffc1-4587-b0d6-f339b4d1e76e', 'cly0mkt000000000000000015', 11, 'Le vendeur lui donna un grand morceau sucré sans rien faire payer.', 'The seller gave her a large, sweet piece without charging anything.'),
  ('57314e36-555b-4870-b36b-e65a278a5b74', 'cly0mkt000000000000000015', 12, 'Lucie ferma les yeux en le goûtant — c''était la meilleure saveur du monde.', 'Lucie closed her eyes tasting it — it was the best flavor in the world.'),
  ('0a01346d-7d93-4e7e-8fc3-58333e46588d', 'cly0mkt000000000000000015', 13, 'Ensuite, elles allèrent à l''étal de pain fraîchement cuit.', 'Afterwards they went to the freshly baked bread stall.'),
  ('8628b8bb-62bb-4ccc-bc6b-fe6e46b74bcc', 'cly0mkt000000000000000015', 14, 'L''odeur était si bonne que Lucie s''arrêta net.', 'The smell was so wonderful that Lucie stopped in her tracks.'),
  ('f36b6618-acd9-4a5c-bb12-1eba040f771f', 'cly0mkt000000000000000015', 15, 'La grand-mère acheta une grande miche et deux brioches à la cannelle.', 'Grandmother bought a large loaf and two cinnamon rolls.'),
  ('99d8bac2-bf70-4d07-a7f4-712f9c8151a5', 'cly0mkt000000000000000015', 16, 'À la fin de la visite, Lucie portait un sac plein de bonnes choses.', 'At the end of the tour, Lucie was carrying a bag full of good things.'),
  ('06243162-2789-4f56-9480-1c19f2f1819e', 'cly0mkt000000000000000015', 17, '— Pourquoi on n''achète pas au supermarché comme tout le monde ? —demanda-t-elle.', '"Why don''t we shop at the supermarket like everyone else?" she asked.'),
  ('3cfe3595-67b1-43a7-b8f6-101fe025059b', 'cly0mkt000000000000000015', 18, 'La grand-mère s''arrêta et la regarda avec un sourire tranquille.', 'Grandmother stopped and looked at her with a calm smile.'),
  ('22d3587f-832b-4ae4-830b-53674f28d649', 'cly0mkt000000000000000015', 19, '— Parce qu''ici on n''achète pas seulement de la nourriture. On achète des histoires —dit-elle.', '"Because here we don''t just buy food. We buy stories," she said.'),
  ('b1db5645-c9a5-4537-8358-8cb35b50afbd', 'cly0sil000000000000000017', 0, 'Elena Voss llevaba veinte años diseñando edificios que la gente olvidaba al día siguiente.', 'Elena Voss had spent twenty years designing buildings people forgot the next day.'),
  ('ff8f77b1-856b-421a-9a7e-1446e57dfe0f', 'cly0sil000000000000000017', 1, 'No era que sus obras fueran malas — eran funcionales, elegantes, correctas.', 'It was not that her works were bad — they were functional, elegant, correct.'),
  ('6cf16e92-492b-4593-858f-ca629adcbecb', 'cly0sil000000000000000017', 2, 'Pero ninguna de ellas había logrado lo que ella consideraba el verdadero objetivo de la arquitectura.', 'But none of them had achieved what she considered the true purpose of architecture.'),
  ('da2a3a79-04c9-4f6c-8101-f6c6a2a8d9a3', 'cly0sil000000000000000017', 3, 'Para Elena, un edificio no debía solo ocupar el espacio — debía transformarlo.', 'For Elena, a building should not merely occupy space — it should transform it.'),
  ('fac59357-69a4-45ed-af43-3d16d8640bc0', 'cly0sil000000000000000017', 4, 'Su obsesión comenzó una tarde en Kioto, cuando entró por error en un jardín zen.', 'Her obsession began one afternoon in Kyoto, when she accidentally entered a Zen garden.'),
  ('d53ab06c-4610-42b1-9abd-bb2f1eea0b2e', 'cly0sil000000000000000017', 5, 'No había nadie. No había ruido. Solo piedras, arena y una quietud que pesaba como el mármol.', 'There was no one. There was no noise. Only stones, sand and a stillness that weighed like marble.'),
  ('e304abd0-99e1-4aed-b4d8-27b7156d7f79', 'cly0sil000000000000000017', 6, 'En ese silencio, Elena sintió algo que no había sentido nunca: que el espacio la escuchaba.', 'In that silence, Elena felt something she had never felt: that the space was listening to her.'),
  ('40344eeb-6816-42a6-a5c9-99366b443f4d', 'cly0sil000000000000000017', 7, 'Volvió a su estudio en Berlín con una sola idea fija: construir el silencio.', 'She returned to her studio in Berlin with a single fixed idea: to build silence.'),
  ('1d81cdf2-1917-4ed2-97c1-466628cab147', 'cly0sil000000000000000017', 8, 'No el silencio de la ausencia, sino el silencio como presencia activa y deliberada.', 'Not the silence of absence, but silence as an active and deliberate presence.'),
  ('4a3b37dc-b11b-412f-ab7f-51a0a85c2f87', 'cly0sil000000000000000017', 9, 'Pasó tres años estudiando acústica, neurociencia y filosofía budista simultáneamente.', 'She spent three years simultaneously studying acoustics, neuroscience and Buddhist philosophy.'),
  ('110833d1-576f-49c9-8c5c-eeb9462255bf', 'cly0sil000000000000000017', 10, 'Sus colegas la observaban con una mezcla de admiración y preocupación genuina.', 'Her colleagues watched her with a mixture of genuine admiration and concern.'),
  ('0fcf0370-0923-44de-adbf-477fcf5f930e', 'cly0sil000000000000000017', 11, 'El encargo llegó inesperadamente: una biblioteca pública en el centro de Hamburgo.', 'The commission arrived unexpectedly: a public library in the centre of Hamburg.'),
  ('b6a26ed8-5606-4751-adbc-99f4b63e5ccb', 'cly0sil000000000000000017', 12, 'La ciudad quería algo moderno, accesible y que atrajera a los jóvenes hacia la lectura.', 'The city wanted something modern, accessible and that would attract young people to reading.'),
  ('a5612179-69c2-40e1-ac61-f2945710c21e', 'cly0sil000000000000000017', 13, 'Elena vio en el proyecto algo completamente distinto: una oportunidad única.', 'Elena saw in the project something entirely different: a unique opportunity.'),
  ('4674bc90-f5d3-4010-a1e2-1ffb3d61c75e', 'cly0sil000000000000000017', 14, 'Diseñó un edificio sin ángulos rectos, donde cada superficie curva absorbía el sonido.', 'She designed a building without right angles, where every curved surface absorbed sound.'),
  ('b822501d-f93c-4f07-961f-d14d87f526aa', 'cly0sil000000000000000017', 15, 'Los materiales eran insólitos: lana prensada, madera porosa, paneles de musgo vivo.', 'The materials were unusual: compressed wool, porous wood, panels of living moss.'),
  ('f8e9a687-0dd7-488f-ba55-1d6119c784fd', 'cly0sil000000000000000017', 16, 'El resultado fue un espacio donde el ruido exterior desaparecía a los tres pasos de la entrada.', 'The result was a space where exterior noise disappeared within three steps of the entrance.'),
  ('198a8865-a063-4a6a-bd4e-9ae9fc52ae50', 'cly0sil000000000000000017', 17, 'Los visitantes describían una sensación extraña: que el tiempo se movía más despacio allí dentro.', 'Visitors described a strange sensation: that time moved more slowly inside.'),
  ('99bcd471-b350-4007-9590-552e64282a03', 'cly0sil000000000000000017', 18, 'Neurocientíficos midieron respuestas cerebrales y confirmaron una reducción significativa del cortisol.', 'Neuroscientists measured brain responses and confirmed a significant reduction in cortisol.'),
  ('c2ba7425-d59f-4d16-b061-e3c83e185baa', 'cly0sil000000000000000017', 19, 'Elena no había construido solo una biblioteca — había construido una forma de escuchar.', 'Elena had not built merely a library — she had built a way of listening.'),
  ('0627aba4-e6c2-41e3-aecf-ed392e50ee24', 'cly0sil000000000000000018', 0, 'Elena Voss avait passé vingt ans à concevoir des bâtiments que les gens oubliaient dès le lendemain.', 'Elena Voss had spent twenty years designing buildings people forgot the next day.'),
  ('c1d7eea6-bebe-44a0-baa4-47a8d3eead82', 'cly0sil000000000000000018', 1, 'Ce n''était pas que ses œuvres étaient mauvaises — elles étaient fonctionnelles, élégantes, correctes.', 'It was not that her works were bad — they were functional, elegant, correct.'),
  ('e51c69ed-8f72-4d91-b6c5-91edf6456f06', 'cly0sil000000000000000018', 2, 'Mais aucune d''elles n''avait atteint ce qu''elle considérait comme le véritable objectif de l''architecture.', 'But none of them had achieved what she considered the true purpose of architecture.'),
  ('5789846d-4434-4229-9b2a-a6e4b47904fd', 'cly0sil000000000000000018', 3, 'Pour Elena, un bâtiment ne devait pas seulement occuper l''espace — il devait le transformer.', 'For Elena, a building should not merely occupy space — it should transform it.'),
  ('3dd90e90-39c9-435a-a3a7-c8b559cec743', 'cly0sil000000000000000018', 4, 'Son obsession commença un après-midi à Kyoto, quand elle entra par erreur dans un jardin zen.', 'Her obsession began one afternoon in Kyoto, when she accidentally entered a Zen garden.'),
  ('b8ac0b2c-3160-46ff-a727-4f28075bc04d', 'cly0sil000000000000000018', 5, 'Il n''y avait personne. Pas de bruit. Seulement des pierres, du sable et un calme qui pesait comme du marbre.', 'There was no one. There was no noise. Only stones, sand and a stillness that weighed like marble.'),
  ('5eeadd51-e989-42ae-9771-3afa120ffa6f', 'cly0sil000000000000000018', 6, 'Dans ce silence, Elena ressentit quelque chose qu''elle n''avait jamais ressenti : que l''espace l''écoutait.', 'In that silence, Elena felt something she had never felt: that the space was listening to her.'),
  ('c5b10ba1-ebeb-420d-89dd-05104df8113e', 'cly0sil000000000000000018', 7, 'Elle retourna dans son studio à Berlin avec une seule idée fixe : construire le silence.', 'She returned to her studio in Berlin with a single fixed idea: to build silence.'),
  ('2aad4bea-6244-4433-a0ae-524db3962bc0', 'cly0sil000000000000000018', 8, 'Pas le silence de l''absence, mais le silence comme présence active et délibérée.', 'Not the silence of absence, but silence as an active and deliberate presence.'),
  ('7da41a10-2a48-4312-b26e-5315fe7506cd', 'cly0sil000000000000000018', 9, 'Elle passa trois ans à étudier simultanément l''acoustique, les neurosciences et la philosophie bouddhiste.', 'She spent three years simultaneously studying acoustics, neuroscience and Buddhist philosophy.'),
  ('8322bb3d-bb0f-40a1-973a-82dce78f893c', 'cly0sil000000000000000018', 10, 'Ses collègues l''observaient avec un mélange d''admiration et d''inquiétude sincère.', 'Her colleagues watched her with a mixture of genuine admiration and concern.'),
  ('101e1e06-98bc-4437-b7cd-72a14df18659', 'cly0sil000000000000000018', 11, 'La commande arriva de façon inattendue : une bibliothèque publique au centre de Hambourg.', 'The commission arrived unexpectedly: a public library in the centre of Hamburg.'),
  ('fa2a9572-805a-4d81-9925-da47962a35ae', 'cly0sil000000000000000018', 12, 'La ville voulait quelque chose de moderne, accessible et qui attirerait les jeunes vers la lecture.', 'The city wanted something modern, accessible and that would attract young people to reading.'),
  ('9f30fac0-263b-4e16-955f-d687d6cecab2', 'cly0sil000000000000000018', 13, 'Elena vit dans le projet quelque chose d''entièrement différent : une opportunité unique.', 'Elena saw in the project something entirely different: a unique opportunity.'),
  ('d7fdc868-ae0d-4f2c-9826-61fec403bad8', 'cly0sil000000000000000018', 14, 'Elle conçut un bâtiment sans angles droits, où chaque surface courbe absorbait le son.', 'She designed a building without right angles, where every curved surface absorbed sound.'),
  ('eb318190-9fdc-44d6-ba77-146b4ecd15bc', 'cly0sil000000000000000018', 15, 'Les matériaux étaient inhabituels : laine compressée, bois poreux, panneaux de mousse vivante.', 'The materials were unusual: compressed wool, porous wood, panels of living moss.'),
  ('8f970cfe-d228-4baa-bc0b-5237cf0af453', 'cly0sil000000000000000018', 16, 'Le résultat fut un espace où le bruit extérieur disparaissait à trois pas de l''entrée.', 'The result was a space where exterior noise disappeared within three steps of the entrance.'),
  ('33846d4b-b5f7-4750-92c8-6a58057afdbc', 'cly0sil000000000000000018', 17, 'Les visiteurs décrivaient une sensation étrange : que le temps se déplaçait plus lentement à l''intérieur.', 'Visitors described a strange sensation: that time moved more slowly inside.'),
  ('75ad0f36-ba25-43ef-9358-44926f99874c', 'cly0sil000000000000000018', 18, 'Des neuroscientifiques mesurèrent les réponses cérébrales et confirmèrent une réduction significative du cortisol.', 'Neuroscientists measured brain responses and confirmed a significant reduction in cortisol.'),
  ('685d0efb-5753-4906-af24-88f8f1cc6011', 'cly0sil000000000000000018', 19, 'Elena n''avait pas seulement construit une bibliothèque — elle avait construit une façon d''écouter.', 'Elena had not built merely a library — she had built a way of listening.'),
  ('893c38da-1827-4693-8dba-0b9711b2c7af', 'cly0dog000000000000000020', 0, 'Tengo un perro. Se llama Bruno.', 'I have a dog. His name is Bruno.'),
  ('fbf3145a-f2a8-4601-8f8f-515e7fc2d0fc', 'cly0dog000000000000000020', 1, 'Bruno es grande y marrón.', 'Bruno is big and brown.'),
  ('b5a268c2-8832-4212-a758-615d885733f6', 'cly0dog000000000000000020', 2, 'Le gusta correr y jugar.', 'He likes to run and play.'),
  ('97fe6f9a-24da-4a30-bd71-93749c2bbdc0', 'cly0dog000000000000000020', 3, 'Hoy vamos al parque.', 'Today we go to the park.'),
  ('c9e815ee-11e9-4b6c-8bec-d86b6e245fa7', 'cly0dog000000000000000020', 4, 'El parque está cerca de mi casa.', 'The park is close to my house.'),
  ('5be7c90f-128d-43bd-949a-ed29077dc1c7', 'cly0dog000000000000000020', 5, 'Bruno ve una pelota roja en el suelo.', 'Bruno sees a red ball on the ground.'),
  ('0df1ffdf-6a44-4616-86f9-2c679c626346', 'cly0dog000000000000000020', 6, 'Corre muy rápido hacia la pelota.', 'He runs very fast toward the ball.'),
  ('21f195b1-c3ee-4c41-b1a6-f6dd62e9e777', 'cly0dog000000000000000020', 7, 'Yo corro también, pero Bruno es más rápido.', 'I run too, but Bruno is faster.'),
  ('499426a9-9b37-4af4-bfaa-ff5f38aae1a3', 'cly0dog000000000000000020', 8, 'Bruno toma la pelota y vuelve a mí.', 'Bruno takes the ball and comes back to me.'),
  ('470522d7-33b9-4f3f-9a35-f35c950747e7', 'cly0dog000000000000000020', 9, '— ¡Bien hecho, Bruno! —digo yo.', '"Well done, Bruno!" I say.'),
  ('e98b5cc0-b0c6-40ff-a538-a8b6ba2a3b64', 'cly0dog000000000000000020', 10, 'Jugamos durante una hora.', 'We play for one hour.'),
  ('d9335390-df7e-45bb-85f9-a944e31f6d9d', 'cly0dog000000000000000020', 11, 'Después, Bruno tiene sed.', 'Afterwards, Bruno is thirsty.'),
  ('9f76ef28-81aa-4de7-892a-40c8a089b517', 'cly0dog000000000000000020', 12, 'Hay un río pequeño en el parque.', 'There is a small river in the park.'),
  ('03e51355-379e-49b6-9b98-d90126af8ada', 'cly0dog000000000000000020', 13, 'Bruno bebe agua del río.', 'Bruno drinks water from the river.'),
  ('1faf19d2-e3f6-49fb-ac1b-25c3f0410375', 'cly0dog000000000000000020', 14, 'Yo bebo agua de mi botella.', 'I drink water from my bottle.'),
  ('f1af1d87-bc41-49ac-8f7c-bf707f7f4b77', 'cly0dog000000000000000020', 15, 'El sol está alto y hace calor.', 'The sun is high and it is hot.'),
  ('7fc6d93f-9091-4019-bd43-fb67309d2652', 'cly0dog000000000000000020', 16, 'Nos sentamos bajo un árbol grande.', 'We sit under a big tree.'),
  ('b19adbfa-87ff-46ab-801c-7912ecbf51f4', 'cly0dog000000000000000020', 17, 'Bruno pone la cabeza en mis piernas.', 'Bruno puts his head on my legs.'),
  ('0dba7aa1-2e51-4ac9-bcd9-b05de0ec2478', 'cly0dog000000000000000020', 18, 'Yo lo acaricio despacio.', 'I pet him slowly.'),
  ('0788ed44-e2c8-47cc-9caa-1504e06096ce', 'cly0dog000000000000000020', 19, 'Bruno es mi mejor amigo.', 'Bruno is my best friend.'),
  ('a4db2233-b6e5-4f01-b1e3-7858550897c5', 'cly0dog000000000000000021', 0, 'J''ai un chien. Il s''appelle Bruno.', 'I have a dog. His name is Bruno.'),
  ('8aa5946a-dd6e-4166-940f-a300cfdfd0ed', 'cly0dog000000000000000021', 1, 'Bruno est grand et marron.', 'Bruno is big and brown.'),
  ('98860d20-13e5-45da-9c30-3662a02ec485', 'cly0dog000000000000000021', 2, 'Il aime courir et jouer.', 'He likes to run and play.'),
  ('92369c07-9154-46c3-a1ab-873561036a22', 'cly0dog000000000000000021', 3, 'Aujourd''hui, nous allons au parc.', 'Today we go to the park.'),
  ('2948c638-f1b0-4337-85d0-6158a7e99d84', 'cly0dog000000000000000021', 4, 'Le parc est près de ma maison.', 'The park is close to my house.'),
  ('b1d6dbc2-4651-4305-93f5-e3393d0f6987', 'cly0dog000000000000000021', 5, 'Bruno voit un ballon rouge par terre.', 'Bruno sees a red ball on the ground.'),
  ('15b3fde7-d1a0-46b7-b844-474fffb7d1d0', 'cly0dog000000000000000021', 6, 'Il court très vite vers le ballon.', 'He runs very fast toward the ball.'),
  ('7ff84632-052b-4916-8356-1428b08b0fff', 'cly0dog000000000000000021', 7, 'Je cours aussi, mais Bruno est plus rapide.', 'I run too, but Bruno is faster.'),
  ('1dc2923b-f2f8-4582-9fb3-8850beb34fb2', 'cly0dog000000000000000021', 8, 'Bruno prend le ballon et revient vers moi.', 'Bruno takes the ball and comes back to me.'),
  ('6c70b606-1b81-44d0-ae57-25671aa4f13c', 'cly0dog000000000000000021', 9, '— Bravo, Bruno ! —je dis.', '"Well done, Bruno!" I say.'),
  ('b2acdc30-68ad-4d1e-82fa-0dc173ec934f', 'cly0dog000000000000000021', 10, 'Nous jouons pendant une heure.', 'We play for one hour.'),
  ('23a9f913-17bc-4815-8f9a-19b57ce4cae0', 'cly0dog000000000000000021', 11, 'Après, Bruno a soif.', 'Afterwards, Bruno is thirsty.'),
  ('0886b3ca-f280-43c4-8a5f-d064ca34543b', 'cly0dog000000000000000021', 12, 'Il y a une petite rivière dans le parc.', 'There is a small river in the park.'),
  ('4ec896ae-bc75-450d-9d54-7b3a8042bd45', 'cly0dog000000000000000021', 13, 'Bruno boit de l''eau de la rivière.', 'Bruno drinks water from the river.'),
  ('e6eeca6e-6c73-44ca-9b09-e30a8d08f8da', 'cly0dog000000000000000021', 14, 'Je bois de l''eau de ma bouteille.', 'I drink water from my bottle.'),
  ('3c73a9ed-321d-4ec5-973c-ecd677bfa7fa', 'cly0dog000000000000000021', 15, 'Le soleil est haut et il fait chaud.', 'The sun is high and it is hot.'),
  ('bfcee77b-f02d-4c37-b752-eb19da14182a', 'cly0dog000000000000000021', 16, 'Nous nous asseyons sous un grand arbre.', 'We sit under a big tree.'),
  ('2683216c-4d1f-4ecc-ae52-cf4059b24251', 'cly0dog000000000000000021', 17, 'Bruno pose la tête sur mes jambes.', 'Bruno puts his head on my legs.'),
  ('10f30817-6ab3-4d57-ab50-e6dde99fe383', 'cly0dog000000000000000021', 18, 'Je le caresse doucement.', 'I pet him slowly.'),
  ('d7c48d7f-67ea-48ca-98ba-c353d08c3419', 'cly0dog000000000000000021', 19, 'Bruno est mon meilleur ami.', 'Bruno is my best friend.'),
  ('59d90558-fa80-4479-8b81-6e85167b8c36', 'cly0trn000000000000000023', 0, 'Clara llegó al andén cuatro minutos después de que el tren partiera.', 'Clara arrived at the platform four minutes after the train had departed.'),
  ('92b1e88d-9bc6-4fa8-a7c0-533d7ea19624', 'cly0trn000000000000000023', 1, 'Miró el tablón de salidas con una mezcla de incredulidad y resignación.', 'She looked at the departures board with a mixture of disbelief and resignation.'),
  ('3c48e263-74ef-4141-92e6-7335227c2d75', 'cly0trn000000000000000023', 2, 'Era el último tren a Sevilla y el siguiente no salía hasta la mañana siguiente.', 'It was the last train to Sevilla and the next one did not leave until the following morning.'),
  ('fb7583f3-8916-4045-bb32-6d5d47faf310', 'cly0trn000000000000000023', 3, 'Se sentó en un banco de metal frío y sacó su teléfono para llamar a la redacción.', 'She sat on a cold metal bench and took out her phone to call the newsroom.'),
  ('73c2c9fb-7328-46c5-9227-ecbfb2b62e94', 'cly0trn000000000000000023', 4, 'La entrevista del día siguiente era con el alcalde — no podía permitirse llegar tarde.', 'The next day''s interview was with the mayor — she could not afford to be late.'),
  ('9b51a0c3-c8af-42c9-a335-38bdcd0db2d1', 'cly0trn000000000000000023', 5, 'Mientras hablaba, un hombre mayor se sentó a su lado con una maleta pequeña.', 'While she was talking, an older man sat down next to her with a small suitcase.'),
  ('44ac2638-e560-432a-9867-688199fc95ae', 'cly0trn000000000000000023', 6, 'Tenía el pelo blanco y los ojos claros de alguien que ha visto mucho mundo.', 'He had white hair and the clear eyes of someone who has seen much of the world.'),
  ('9d09ba22-83a5-4612-82a3-6ddc8c39c70a', 'cly0trn000000000000000023', 7, '— ¿También perdió el tren? —preguntó él con una sonrisa tranquila.', '"Did you also miss the train?" he asked with a calm smile.'),
  ('3a261b52-da3a-4611-8c06-999236eaa85c', 'cly0trn000000000000000023', 8, '— Sí, por cuatro malditos minutos —respondió Clara, sin ocultar su frustración.', '"Yes, by four damned minutes," replied Clara, not hiding her frustration.'),
  ('004bc781-eb97-4298-9c18-eb7173dd367f', 'cly0trn000000000000000023', 9, '— Cuatro minutos —repitió él pensativo—. Una vez llegué cuatro minutos tarde a una cita y me cambió la vida.', '"Four minutes," he repeated thoughtfully. "Once I arrived four minutes late to an appointment and it changed my life."'),
  ('7d6ab59d-b908-49eb-8cd9-cecb8bdd8f3a', 'cly0trn000000000000000023', 10, 'Clara lo miró con curiosidad, a pesar de sí misma.', 'Clara looked at him with curiosity, despite herself.'),
  ('93a9e2cf-81d9-46cc-a8d9-cd610fe42a68', 'cly0trn000000000000000023', 11, 'El hombre, que se llamaba Aurelio, era relojero retirado de Córdoba.', 'The man, whose name was Aurelio, was a retired watchmaker from Córdoba.'),
  ('e8725c9b-9f1b-41cd-a109-63aa743a1801', 'cly0trn000000000000000023', 12, 'Había pasado cincuenta años arreglando relojes y había llegado a una conclusión radical.', 'He had spent fifty years repairing clocks and had reached a radical conclusion.'),
  ('4037741f-8ed4-43d3-8646-662278344bbc', 'cly0trn000000000000000023', 13, '— El tiempo no se pierde nunca —dijo—. Simplemente cambia de forma.', '"Time is never lost," he said. "It simply changes form."'),
  ('e81fe974-9794-4f96-8353-faaabdcec58c', 'cly0trn000000000000000023', 14, 'Clara, acostumbrada a pensar en plazos y deadlines, encontró la idea perturbadora.', 'Clara, accustomed to thinking in deadlines and due dates, found the idea unsettling.'),
  ('e2b50794-1b8c-447c-afd0-36e431ee481b', 'cly0trn000000000000000023', 15, '— Eso es fácil de decir cuando uno está jubilado —respondió con cierta ironía.', '"That is easy to say when one is retired," she replied with a touch of irony.'),
  ('953b1c32-e7b6-45e2-8018-a24017b8e1e8', 'cly0trn000000000000000023', 16, 'Aurelio se rió — una risa genuina, sin ofensa.', 'Aurelio laughed — a genuine laugh, without offence.'),
  ('63ee363d-6f7b-480e-95bc-aade17ce8f90', 'cly0trn000000000000000023', 17, 'Pasaron tres horas hablando sobre el tiempo, el periodismo y los relojes rotos.', 'They spent three hours talking about time, journalism and broken clocks.'),
  ('0694866f-5b69-47a2-9ccb-8fd00e5542e8', 'cly0trn000000000000000023', 18, 'Cuando llegó el primer tren de la mañana, Clara se dio cuenta de que no había mirado el teléfono en horas.', 'When the first morning train arrived, Clara realised she had not looked at her phone in hours.'),
  ('e3130198-610d-4c6f-9e1b-815899042a11', 'cly0trn000000000000000023', 19, 'Subió al tren pensando que quizás perder cuatro minutos había sido la mejor inversión de su año.', 'She boarded the train thinking that perhaps missing four minutes had been the best investment of her year.'),
  ('6303f9a7-adda-4152-8270-47e978978c80', 'cly0trn000000000000000024', 0, 'Clara arriva sur le quai quatre minutes après le départ du train.', 'Clara arrived at the platform four minutes after the train had departed.'),
  ('84df952a-2e4f-47ed-b253-7da0444f7c2e', 'cly0trn000000000000000024', 1, 'Elle regarda le tableau des départs avec un mélange d''incrédulité et de résignation.', 'She looked at the departures board with a mixture of disbelief and resignation.'),
  ('e85faa36-cb87-4f25-b021-19e8424c8dbb', 'cly0trn000000000000000024', 2, 'C''était le dernier train pour Séville et le suivant ne partait que le lendemain matin.', 'It was the last train to Sevilla and the next one did not leave until the following morning.'),
  ('1d823aa8-005e-4734-b382-df44ad3100e1', 'cly0trn000000000000000024', 3, 'Elle s''assit sur un banc en métal froid et sortit son téléphone pour appeler la rédaction.', 'She sat on a cold metal bench and took out her phone to call the newsroom.'),
  ('d749c4ec-998c-4442-a608-9f02e68fd6c8', 'cly0trn000000000000000024', 4, 'L''interview du lendemain était avec le maire — elle ne pouvait pas se permettre d''être en retard.', 'The next day''s interview was with the mayor — she could not afford to be late.'),
  ('0199fe0f-72fb-4d3d-8493-0937c4cdfe0a', 'cly0trn000000000000000024', 5, 'Pendant qu''elle parlait, un homme plus âgé s''assit à côté d''elle avec une petite valise.', 'While she was talking, an older man sat down next to her with a small suitcase.'),
  ('45556389-248a-4c91-aa9a-3fd58df8c67e', 'cly0trn000000000000000024', 6, 'Il avait les cheveux blancs et les yeux clairs de quelqu''un qui a beaucoup voyagé.', 'He had white hair and the clear eyes of someone who has seen much of the world.'),
  ('edad44cd-adb5-475a-93dd-330f2b69a308', 'cly0trn000000000000000024', 7, '— Vous avez aussi raté le train ? —demanda-t-il avec un sourire tranquille.', '"Did you also miss the train?" he asked with a calm smile.'),
  ('bbf39b4d-3284-4726-b05e-78da32371146', 'cly0trn000000000000000024', 8, '— Oui, de quatre maudites minutes —répondit Clara sans cacher sa frustration.', '"Yes, by four damned minutes," replied Clara, not hiding her frustration.'),
  ('4eeb229f-60a2-49ad-9209-7625898fb24e', 'cly0trn000000000000000024', 9, '— Quatre minutes —répéta-t-il pensivement—. Une fois, je suis arrivé quatre minutes en retard à un rendez-vous et ça a changé ma vie.', '"Four minutes," he repeated thoughtfully. "Once I arrived four minutes late to an appointment and it changed my life."'),
  ('57c01cb8-4a2f-4674-aff6-b07ff57a965a', 'cly0trn000000000000000024', 10, 'Clara le regarda avec curiosité, malgré elle.', 'Clara looked at him with curiosity, despite herself.'),
  ('dc75ae32-8f14-4f90-ac0e-76e7356cdc7c', 'cly0trn000000000000000024', 11, 'L''homme, qui s''appelait Aurélien, était horloger retraité de Cordoue.', 'The man, whose name was Aurélien, was a retired watchmaker from Córdoba.'),
  ('b9f57419-8763-4c60-97db-e9bcf0d5cefc', 'cly0trn000000000000000024', 12, 'Il avait passé cinquante ans à réparer des montres et était arrivé à une conclusion radicale.', 'He had spent fifty years repairing clocks and had reached a radical conclusion.'),
  ('80f8dbaa-2889-406d-8321-e754e8fed283', 'cly0trn000000000000000024', 13, '— Le temps ne se perd jamais —dit-il—. Il change simplement de forme.', '"Time is never lost," he said. "It simply changes form."'),
  ('bf2edc1b-3723-4db8-9dd7-18c7f73dd212', 'cly0trn000000000000000024', 14, 'Clara, habituée à penser en délais et en échéances, trouva l''idée dérangeante.', 'Clara, accustomed to thinking in deadlines and due dates, found the idea unsettling.'),
  ('11180b37-0287-44c3-a2ed-d75e3baff182', 'cly0trn000000000000000024', 15, '— C''est facile à dire quand on est à la retraite —répondit-elle avec une certaine ironie.', '"That is easy to say when one is retired," she replied with a touch of irony.'),
  ('9aeb7c95-5e57-4de5-9c52-12a03756f0d1', 'cly0trn000000000000000024', 16, 'Aurélien rit — un rire sincère, sans offense.', 'Aurélien laughed — a genuine laugh, without offence.'),
  ('77f5ea49-bb70-4090-8d81-790edb8b383a', 'cly0trn000000000000000024', 17, 'Ils passèrent trois heures à parler du temps, du journalisme et des montres cassées.', 'They spent three hours talking about time, journalism and broken clocks.'),
  ('26e97d7d-7c6c-4b2c-887f-39c245efd8d6', 'cly0trn000000000000000024', 18, 'Quand le premier train du matin arriva, Clara réalisa qu''elle n''avait pas regardé son téléphone depuis des heures.', 'When the first morning train arrived, Clara realised she had not looked at her phone in hours.'),
  ('a7a32886-fe3b-4804-96a1-66a5d4039ee6', 'cly0trn000000000000000024', 19, 'Elle monta dans le train en pensant que rater quatre minutes avait peut-être été le meilleur investissement de son année.', 'She boarded the train thinking that perhaps missing four minutes had been the best investment of her year.'),
  ('09ba6032-1e68-4e1c-bf4a-e85ed099e57f', 'cly0map000000000000000026', 0, 'El doctor Héctor Salinas llevaba una década cartografiando lo que otros no podían ver: la geografía íntima de los recuerdos ajenos.', 'Dr Héctor Salinas had spent a decade mapping what others could not see: the intimate geography of other people''s memories.'),
  ('36dc78f8-7876-461a-99d9-126bc2f24fe7', 'cly0map000000000000000026', 1, 'Su laboratorio en la Universidad Autónoma de Madrid era una sala sin ventanas llena de escáneres, electrodos y silencio meticulosamente cultivado.', 'His laboratory at the Universidad Autónoma de Madrid was a windowless room full of scanners, electrodes and meticulously cultivated silence.'),
  ('e2e18642-23e5-4ef6-bdd6-f6bc4acae06f', 'cly0map000000000000000026', 2, 'El procedimiento, que él llamaba cartografía mnémica, permitía traducir las estructuras neuronales del hipocampo en imágenes tridimensionales navegables.', 'The procedure, which he called mnemonic cartography, allowed the neural structures of the hippocampus to be translated into navigable three-dimensional images.'),
  ('2b14b506-90fc-4077-a129-9930c1bfeab0', 'cly0map000000000000000026', 3, 'No era lectura de mente — era algo más sutil y, en cierto modo, más perturbador.', 'It was not mind reading — it was something more subtle and, in a certain sense, more disturbing.'),
  ('50c778f5-2506-4b14-a728-7718e25f9aa6', 'cly0map000000000000000026', 4, 'Era la posibilidad de ver cómo el pasado de una persona había esculpido la arquitectura de su presente.', 'It was the possibility of seeing how a person''s past had sculpted the architecture of their present.'),
  ('553da021-6bfd-42df-9d7a-ea6d36104a98', 'cly0map000000000000000026', 5, 'Su sujeto más reciente era una mujer de setenta y dos años llamada Isabel, que padecía una forma rápidamente progresiva de demencia frontotemporal.', 'His most recent subject was a seventy-two-year-old woman named Isabel, who suffered from a rapidly progressive form of frontotemporal dementia.'),
  ('66eaf299-dccd-48e7-881a-58794dd5a9d2', 'cly0map000000000000000026', 6, 'En cuestión de meses, Isabel había perdido el lenguaje, el reconocimiento facial y la mayoría de los recuerdos episódicos de su vida adulta.', 'Within months, Isabel had lost language, facial recognition and most of the episodic memories of her adult life.'),
  ('e4cc08c8-b8cb-43e5-8cf6-1253c22d1b04', 'cly0map000000000000000026', 7, 'Sin embargo, cuando escuchaba determinadas melodías de los años sesenta, algo en ella respondía con una vitalidad desconcertante.', 'However, when she heard certain melodies from the nineteen-sixties, something in her responded with a disconcerting vitality.'),
  ('d04bc91d-1039-47bf-8293-7be5981ba857', 'cly0map000000000000000026', 8, 'Héctor había comenzado el estudio con hipótesis rigurosas y metodología impecable.', 'Héctor had begun the study with rigorous hypotheses and impeccable methodology.'),
  ('88faee90-99a5-4840-8319-0ea4c0a89a2d', 'cly0map000000000000000026', 9, 'Pero con Isabel, algo se había torcido en la ecuación entre ciencia y humanidad.', 'But with Isabel, something had become skewed in the equation between science and humanity.'),
  ('0dce1547-f1a7-4945-a736-e712ff102023', 'cly0map000000000000000026', 10, 'Los mapas mostraban islas de memoria intacta flotando en un océano de vacío neuronal.', 'The maps showed islands of intact memory floating in an ocean of neural void.'),
  ('a02a5d29-449f-4caf-933c-36b334f46849', 'cly0map000000000000000026', 11, 'Algunas de esas islas correspondían a momentos aparentemente insignificantes: el olor de una cocina, la textura de una tela, el ritmo de una voz.', 'Some of those islands corresponded to seemingly insignificant moments: the smell of a kitchen, the texture of a fabric, the rhythm of a voice.'),
  ('c933dd12-aff0-4348-bc5b-5426e986ad62', 'cly0map000000000000000026', 12, 'La pregunta que lo desvelaba por las noches no era científica sino filosófica.', 'The question that kept him awake at night was not scientific but philosophical.'),
  ('719b1173-7fc9-41fb-968d-1b4d6642523d', 'cly0map000000000000000026', 13, 'Si una persona no puede recordar quién fue, ¿sigue siendo la misma persona?', 'If a person cannot remember who they were, are they still the same person?'),
  ('13e4bab4-797e-43e2-8a55-2226cfdca58c', 'cly0map000000000000000026', 14, 'La neurociencia ortodoxa respondería que la identidad es una ilusión narrativa que el cerebro construye retrospectivamente.', 'Orthodox neuroscience would answer that identity is a narrative illusion that the brain constructs retrospectively.'),
  ('dd94bada-4751-4b66-b7a4-c2a7d7205c15', 'cly0map000000000000000026', 15, 'Pero los mapas de Isabel sugerían algo que ningún modelo teórico había contemplado.', 'But Isabel''s maps suggested something no theoretical model had considered.'),
  ('1143d918-775d-4e22-b26f-9977623d396c', 'cly0map000000000000000026', 16, 'Había un patrón residual que persistía a través de toda la devastación cognitiva — una firma neuronal constante, casi como una huella digital del alma.', 'There was a residual pattern that persisted through all the cognitive devastation — a constant neural signature, almost like a fingerprint of the soul.'),
  ('2b4bf91b-3b42-411c-9f1d-17393a454bb7', 'cly0map000000000000000026', 17, 'Héctor pasó semanas debatiendo consigo mismo si publicar ese hallazgo o suprimirlo.', 'Héctor spent weeks debating with himself whether to publish that finding or suppress it.'),
  ('97c388a1-8600-4ce3-80b3-b1cc92d7a37c', 'cly0map000000000000000026', 18, 'Publicarlo implicaría abrir una caja de Pandora teológica que la comunidad científica no estaba preparada para gestionar.', 'Publishing it would mean opening a theological Pandora''s box that the scientific community was not ready to manage.'),
  ('748d997d-d576-4650-a377-69ab51b4dc33', 'cly0map000000000000000026', 19, 'Al final optó por algo intermedio: guardó los datos en un archivo cifrado y visitó a Isabel todos los martes, sin electrodos, sin escáneres, simplemente para escuchar la música con ella.', 'In the end he chose something in between: he saved the data in an encrypted file and visited Isabel every Tuesday, without electrodes, without scanners, simply to listen to the music with her.'),
  ('f45ba792-c295-40d9-a5b8-b9ad36763180', 'cly0map000000000000000027', 0, 'Le docteur Héctor Salinas passait depuis une décennie à cartographier ce que les autres ne pouvaient voir : la géographie intime des souvenirs d''autrui.', 'Dr Héctor Salinas had spent a decade mapping what others could not see: the intimate geography of other people''s memories.'),
  ('5dbd2467-47bf-4207-8ee2-7a757c3c03cf', 'cly0map000000000000000027', 1, 'Son laboratoire à l''Université Autonome de Madrid était une salle sans fenêtres remplie de scanners, d''électrodes et d''un silence méticuleusement cultivé.', 'His laboratory at the Universidad Autónoma de Madrid was a windowless room full of scanners, electrodes and meticulously cultivated silence.'),
  ('3d962eb9-95a9-461e-9f30-533ac0b744f6', 'cly0map000000000000000027', 2, 'La procédure, qu''il appelait cartographie mnémique, permettait de traduire les structures neuronales de l''hippocampe en images tridimensionnelles navigables.', 'The procedure, which he called mnemonic cartography, allowed the neural structures of the hippocampus to be translated into navigable three-dimensional images.'),
  ('e5f9dcc7-c942-4e61-821e-894b0b9b6b75', 'cly0map000000000000000027', 3, 'Ce n''était pas de la lecture dans les pensées — c''était quelque chose de plus subtil et, dans un certain sens, de plus dérangeant.', 'It was not mind reading — it was something more subtle and, in a certain sense, more disturbing.'),
  ('0900b4d3-dabe-4f47-b883-c2cc07e2dc4f', 'cly0map000000000000000027', 4, 'C''était la possibilité de voir comment le passé d''une personne avait sculpté l''architecture de son présent.', 'It was the possibility of seeing how a person''s past had sculpted the architecture of their present.'),
  ('17055319-3c93-454c-9b12-cc196b212a7c', 'cly0map000000000000000027', 5, 'Son sujet le plus récent était une femme de soixante-douze ans prénommée Isabelle, qui souffrait d''une forme rapidement progressive de démence frontotemporale.', 'His most recent subject was a seventy-two-year-old woman named Isabelle, who suffered from a rapidly progressive form of frontotemporal dementia.'),
  ('2d6e7fe2-27fa-42ee-b13b-1f1d6dd271a6', 'cly0map000000000000000027', 6, 'En l''espace de quelques mois, Isabelle avait perdu le langage, la reconnaissance des visages et la plupart des souvenirs épisodiques de sa vie adulte.', 'Within months, Isabelle had lost language, facial recognition and most of the episodic memories of her adult life.'),
  ('ae2203ac-956c-4805-bedc-bee0634e1bac', 'cly0map000000000000000027', 7, 'Pourtant, lorsqu''elle entendait certaines mélodies des années soixante, quelque chose en elle répondait avec une vitalité déconcertante.', 'However, when she heard certain melodies from the nineteen-sixties, something in her responded with a disconcerting vitality.'),
  ('1573e2bc-479b-4666-ae59-f67957f4c02d', 'cly0map000000000000000027', 8, 'Héctor avait commencé l''étude avec des hypothèses rigoureuses et une méthodologie irréprochable.', 'Héctor had begun the study with rigorous hypotheses and impeccable methodology.'),
  ('bd75cc6b-abed-4bb5-8254-d186018ff30a', 'cly0map000000000000000027', 9, 'Mais avec Isabelle, quelque chose s''était déréglé dans l''équation entre science et humanité.', 'But with Isabelle, something had become skewed in the equation between science and humanity.'),
  ('d39a5e04-158a-46a2-9718-909cd45f078a', 'cly0map000000000000000027', 10, 'Les cartes montraient des îles de mémoire intacte flottant dans un océan de vide neuronal.', 'The maps showed islands of intact memory floating in an ocean of neural void.'),
  ('090b8d77-215d-4566-8437-dff200b89a8a', 'cly0map000000000000000027', 11, 'Certaines de ces îles correspondaient à des moments apparemment insignifiants : l''odeur d''une cuisine, la texture d''un tissu, le rythme d''une voix.', 'Some of those islands corresponded to seemingly insignificant moments: the smell of a kitchen, the texture of a fabric, the rhythm of a voice.'),
  ('67d8f01b-af3a-4481-bcf9-461f3f1b21e7', 'cly0map000000000000000027', 12, 'La question qui le tenait éveillé la nuit n''était pas scientifique mais philosophique.', 'The question that kept him awake at night was not scientific but philosophical.'),
  ('b770622d-9946-43bd-9c63-c71066d7af30', 'cly0map000000000000000027', 13, 'Si une personne ne peut pas se souvenir de qui elle était, est-elle encore la même personne ?', 'If a person cannot remember who they were, are they still the same person?'),
  ('6f5fefa9-0d7e-45e5-8b65-2bf038f5e3a4', 'cly0map000000000000000027', 14, 'La neuroscience orthodoxe répondrait que l''identité est une illusion narrative que le cerveau construit rétrospectivement.', 'Orthodox neuroscience would answer that identity is a narrative illusion that the brain constructs retrospectively.'),
  ('1c3eb2c1-891a-43f9-a3b0-bcbdda4b6dcd', 'cly0map000000000000000027', 15, 'Mais les cartes d''Isabelle suggéraient quelque chose qu''aucun modèle théorique n''avait envisagé.', 'But Isabelle''s maps suggested something no theoretical model had considered.'),
  ('273b7a14-a436-48a0-bb1b-806c5d33fd9d', 'cly0map000000000000000027', 16, 'Il y avait un schéma résiduel qui persistait à travers toute la dévastation cognitive — une signature neuronale constante, presque comme une empreinte digitale de l''âme.', 'There was a residual pattern that persisted through all the cognitive devastation — a constant neural signature, almost like a fingerprint of the soul.'),
  ('a5ed29ea-5197-4517-896d-5fe15bdfbcdf', 'cly0map000000000000000027', 17, 'Héctor passa des semaines à débattre avec lui-même s''il fallait publier cette découverte ou la dissimuler.', 'Héctor spent weeks debating with himself whether to publish that finding or suppress it.'),
  ('c23febd2-fb76-4434-a0ce-a660d51e023a', 'cly0map000000000000000027', 18, 'La publier impliquerait d''ouvrir une boîte de Pandore théologique que la communauté scientifique n''était pas prête à gérer.', 'Publishing it would mean opening a theological Pandora''s box that the scientific community was not ready to manage.'),
  ('3ad9cac7-5133-47f4-bd63-772c099a8452', 'cly0map000000000000000027', 19, 'Il opta finalement pour une voie intermédiaire : il conserva les données dans un fichier chiffré et rendit visite à Isabelle chaque mardi, sans électrodes, sans scanners, simplement pour écouter la musique avec elle.', 'In the end he chose something in between: he saved the data in an encrypted file and visited Isabelle every Tuesday, without electrodes, without scanners, simply to listen to the music with her.')
